import ExcelJS from 'exceljs';

export const exportToExcel = (projectDetails, sections) => {
    const workbook = new ExcelJS.Workbook();
    const worksheet = workbook.addWorksheet('Project Details');

    // Function to apply styles to cells
    const applyStyles = (cell, options) => {
        cell.font = options.font || {};
        cell.alignment = options.alignment || {};
        cell.border = options.border || {};
        cell.fill = options.fill || {};
        cell.numFmt = options.numFmt || '';
    };

    // Function to add rows with data and style
    const addRowWithStyle = (rowData, options = {}) => {
        const row = worksheet.addRow(rowData);
        row.eachCell((cell) => {
            applyStyles(cell, options);
        });
    };

    // Header style
    const headerStyle = {
        font: { bold: true, size: 12, color: { argb: 'FFFFFF' } }, // White bold font
        fill: { type: 'pattern', pattern: 'solid', fgColor: { argb: '2E75B6' } }, // Blue fill color
        alignment: { horizontal: 'center' },
        border: { top: { style: 'thin' }, left: { style: 'thin' }, bottom: { style: 'thin' }, right: { style: 'thin' } },
    };

    // Content style
    const contentStyle = {
        font: { size: 11 },
        alignment: { horizontal: 'left' },
        border: { top: { style: 'thin' }, left: { style: 'thin' }, bottom: { style: 'thin' }, right: { style: 'thin' } },
    };

    // Add project details to the worksheet with styles
    addRowWithStyle(['Project Name', projectDetails.projectName], contentStyle);
    addRowWithStyle(['Client', projectDetails.client], contentStyle);
    addRowWithStyle(['Contractor', projectDetails.contractor], contentStyle);
    addRowWithStyle(['Consultant', projectDetails.consultant], contentStyle);
    addRowWithStyle(['Title', projectDetails.title], contentStyle);
    worksheet.addRow([]); // Empty row for spacing

    // Function to add sections and their data to the worksheet
    const addDataToSectionsSheet = (section) => {
        addRowWithStyle(['Section Name', section.section_name], headerStyle);
        worksheet.addRow([]); // Empty row for spacing

        if (section.subsections) {
            section.subsections.forEach((subsection) => {
                addRowWithStyle(['Subsection Name', subsection.subsection_name], headerStyle);
                worksheet.addRow([]); // Empty row for spacing

                if (subsection.documents) {
                    subsection.documents.forEach((document) => {
                        addRowWithStyle(['Document Name', `${document.serial_number}-${document.document_name}`], contentStyle);
                        addRowWithStyle(['Start Date', document.start_date || 'N/A'], contentStyle);
                        addRowWithStyle(['End Date', document.end_date || 'N/A'], contentStyle);
                        addRowWithStyle(['Status', document.status || 'N/A'], contentStyle);
                        addRowWithStyle(['Priority', document.priority || 'N/A'], contentStyle);
                        addRowWithStyle(['Assigned To', document.assigned_to || 'N/A'], contentStyle);
                        addRowWithStyle(['Progress', document.progress || 'N/A'], contentStyle);
                        worksheet.addRow([]); // Empty row for spacing
                    });
                }
            });
        }
    };

    // Iterate over sections and add their data with styles
    if (sections) {
        sections.forEach((section) => {
            addDataToSectionsSheet(section);
        });
    }

    // Save the workbook
    workbook.xlsx.writeBuffer().then((buffer) => {
        const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'project_details.xlsx';
        a.click();
        URL.revokeObjectURL(url);
    });
};
